import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第五十六卦 旅 火山旅 離上艮下","description":"周易 - 第五十六卦 旅 火山旅 離上艮下","frontmatter":{"title":"第五十六卦 旅 火山旅 離上艮下","description":"周易 - 第五十六卦 旅 火山旅 離上艮下"},"headers":[],"relativePath":"classics/zhouyi/057.md","filePath":"classics/zhouyi/057.md"}'),l={name:"classics/zhouyi/057.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="旅" tabindex="-1">旅 <a class="header-anchor" href="#旅" aria-label="Permalink to “旅”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>小亨，旅貞吉。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>旅，小亨，柔得中乎外，而順乎剛，止而麗乎明，是以小亨，旅貞吉也。旅之時義大矣哉！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>山上有火，旅；君子以明慎用刑，而不留獄。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>旅瑣瑣，斯其所取災。象 曰：旅瑣瑣，志窮災也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>旅即次，懷其資，得童僕貞。象曰：得童僕貞，終無尤也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>旅焚其次，喪其童僕，貞厲。象曰：旅焚其次，亦以傷矣。以旅與下，其義喪也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>旅於處，得其資斧，我心不快。象曰：旅於處，未得位也。得其資斧，心未快也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>射雉一矢亡，終以譽命。象曰：終以譽命，上逮也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>鳥焚其巢，旅人先笑後號啕。喪牛於易，兇。象曰：以旅在上，其義焚也。喪牛於易，終莫之聞也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
